//! each melody note's MIDI number to the harmony notes produced for it. This
//! is critical for random modes (4-5) where the harmony interval is chosen
//! randomly on Note-On and must be released with the same notes on Note-Off.

use std::collections::HashMap;
use wmidi::Note;

use crate::config::{BeatPhase, HarmonyMode, Key, OctaveMode, ScaleMode};
use crate::functional;
use crate::functional::context::HarmonicContext;
use crate::modes;
use crate::scale::Scale;
use crate::stateful::{
    ContraryMotionState, CounterpointSpecies, CounterpointState, CounterpointStrictness,
