        advance_to_beat(&transport, 1.5);
        let out = lane.tick(&world);
        assert_eq!(out.ops.len(), 1);
        match &out.ops[0] {
            DispatchOp::NoteOn { note, .. } => assert_eq!(*note, 60),
            _ => panic!("expected NoteOn"),
        }
    }

